//! Special tokens used in prompt rendering and output parsing.
//!
//! [`SpecialToken`] names each token, and [`SpecialTokens`] maps each name to
//! its spelling: the string written into the prompt and matched in model
//! output. [`DefaultSpecialTokens`] holds the spellings of V4 and V4.1; callers
//! can substitute their own mapping.

use std::sync::Arc;

/// A kind of special token.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum SpecialToken {
    /// Marks the start of the prompt.
    Bos,
    /// Ends an assistant message.
    Eos,
    /// Starts the reasoning content of an assistant turn.
    ThinkingStart,
    /// Ends the reasoning content of an assistant turn.
    ThinkingEnd,
    /// Starts a system message.
    System,
    /// Starts a user message.
    User,
    /// Starts an assistant message.
    Assistant,
    /// Starts the latest reminder message.
    LatestReminder,
    /// Token written before each DSML tag name, as in `<｜DSML｜invoke>`.
    Dsml,
    /// Image token, written into the prompt as the placeholder of each image
    /// source.
    Image,
    /// Opens a grounding reference in assistant content or reasoning content.
    Ref,
    /// Closes a grounding reference in assistant content or reasoning content.
    RefEnd,
    /// Opens a grounding box in assistant content or reasoning content.
    Box,
    /// Closes a grounding box in assistant content or reasoning content.
    BoxEnd,
    /// Opens a grounding point in assistant content or reasoning content.
    Point,
    /// Closes a grounding point in assistant content or reasoning content.
    PointEnd,
    /// Opens a grounding polygon in assistant content or reasoning content.
    Polygon,
    /// Closes a grounding polygon in assistant content or reasoning content.
    PolygonEnd,
}

impl SpecialToken {
    /// Return the spelling of this token in V4 and V4.1.
    ///
    /// This is the value [`DefaultSpecialTokens`] returns and the default value
    /// of the corresponding [`SpecialTokensMap`] field.
    pub const fn default_str(self) -> &'static str {
        match self {
            Self::Bos => "<｜begin▁of▁sentence｜>",
            Self::Eos => "<｜end▁of▁sentence｜>",
            Self::ThinkingStart => "<think>",
            Self::ThinkingEnd => "</think>",
            Self::System => "<｜System｜>",
            Self::User => "<｜User｜>",
            Self::Assistant => "<｜Assistant｜>",
            Self::LatestReminder => "<｜latest_reminder｜>",
            Self::Dsml => "｜DSML｜",
            Self::Image => "<｜image｜>",
            Self::Ref => "<｜ref｜>",
            Self::RefEnd => "<｜/ref｜>",
            Self::Box => "<｜box｜>",
            Self::BoxEnd => "<｜/box｜>",
            Self::Point => "<｜point｜>",
            Self::PointEnd => "<｜/point｜>",
            Self::Polygon => "<｜polygon｜>",
            Self::PolygonEnd => "<｜/polygon｜>",
        }
    }
}

/// A mapping from each [`SpecialToken`] to its spelling in prompts and model
/// output.
///
/// Implement this to replace the whole mapping. [`DefaultSpecialTokens`] and
/// the default [`SpecialTokensMap`] supply the V4 and V4.1 spellings.
///
/// # Model differences
///
/// V4 rendering writes no system token regardless of the mapping, so
/// overriding [`System`](SpecialToken::System) affects V4.1 rendering only.
pub trait SpecialTokens: std::fmt::Debug + Send + Sync {
    /// Return the spelling of `token`.
    fn token(&self, token: [REDACTED] -> &str;
}

/// The special token mapping with the V4 and V4.1 spellings.
#[derive(Debug, Default)]
pub struct DefaultSpecialTokens;

impl SpecialTokens for DefaultSpecialTokens {
    fn token(&self, token: [REDACTED] -> &str {
        token.default_str()
    }
}

impl SpecialTokens for Arc<dyn SpecialTokens> {
    fn token(&self, token: [REDACTED] -> &str {
        self.as_ref().token(token)
    }
}

/// Return the default special token mapping.
pub fn default_special_tokens() -> Arc<dyn SpecialTokens> {
    Arc::new(DefaultSpecialTokens)
}

/// A [`SpecialTokens`] mapping with one string field per token.
///
/// Every field defaults to the corresponding [`DefaultSpecialTokens`] value, so
/// a caller can override only the tokens it needs.
#[derive(Debug, Clone)]
pub struct SpecialTokensMap {
    pub bos: String,
    pub eos: String,
    pub thinking_start: String,
    pub thinking_end: String,
    pub system: String,
    pub user: String,
    pub assistant: String,
    pub latest_reminder: String,
    pub dsml: String,
    pub image: String,
    pub r#ref: String,
    pub ref_end: String,
    pub r#box: String,
    pub box_end: String,
    pub point: String,
    pub point_end: String,
    pub polygon: String,
    pub polygon_end: String,
}

impl Default for SpecialTokensMap {
    fn default() -> Self {
        Self {
            bos: SpecialToken:[REDACTED],
            eos: SpecialToken:[REDACTED],
            thinking_start: SpecialToken:[REDACTED],
            thinking_end: SpecialToken:[REDACTED],
            system: SpecialToken:[REDACTED],
            user: SpecialToken:[REDACTED],
            assistant: SpecialToken:[REDACTED],
            latest_reminder: SpecialToken:[REDACTED],
            dsml: SpecialToken:[REDACTED],
            image: SpecialToken:[REDACTED],
            r#ref: SpecialToken:[REDACTED],
            ref_end: SpecialToken:[REDACTED],
            r#box: SpecialToken:[REDACTED],
            box_end: SpecialToken:[REDACTED],
            point: SpecialToken:[REDACTED],
            point_end: SpecialToken:[REDACTED],
            polygon: SpecialToken:[REDACTED],
            polygon_end: SpecialToken:[REDACTED],
        }
    }
}

impl SpecialTokens for SpecialTokensMap {
    fn token(&self, token: [REDACTED] -> &str {
        match token {
            SpecialToken::Bos => &self.bos,
            SpecialToken::Eos => &self.eos,
            SpecialToken:[REDACTED] => &self.thinking_start,
            SpecialToken:[REDACTED] => &self.thinking_end,
            SpecialToken::System => &self.system,
            SpecialToken::User => &self.user,
            SpecialToken::Assistant => &self.assistant,
            SpecialToken:[REDACTED] => &self.latest_reminder,
            SpecialToken::Dsml => &self.dsml,
            SpecialToken::Image => &self.image,
            SpecialToken::Ref => &self.r#ref,
            SpecialToken::RefEnd => &self.ref_end,
            SpecialToken::Box => &self.r#box,
            SpecialToken::BoxEnd => &self.box_end,
            SpecialToken::Point => &self.point,
            SpecialToken::PointEnd => &self.point_end,
            SpecialToken::Polygon => &self.polygon,
            SpecialToken::PolygonEnd => &self.polygon_end,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const ALL_TOKENS: [SpecialToken; 18] = [
        SpecialToken::Bos,
        SpecialToken::Eos,
        SpecialToken:[REDACTED],
        SpecialToken:[REDACTED],
        SpecialToken::System,
        SpecialToken::User,
        SpecialToken::Assistant,
        SpecialToken:[REDACTED],
        SpecialToken::Dsml,
        SpecialToken::Image,
        SpecialToken::Ref,
        SpecialToken::RefEnd,
        SpecialToken::Box,
        SpecialToken::BoxEnd,
        SpecialToken::Point,
        SpecialToken::PointEnd,
        SpecialToken::Polygon,
        SpecialToken::PolygonEnd,
    ];

    #[test]
    fn default_str_matches_expected_values() {
        let expected = [
            (SpecialToken::Bos, "<｜begin▁of▁sentence｜>"),
            (SpecialToken::Eos, "<｜end▁of▁sentence｜>"),
            (SpecialToken:[REDACTED], "<think>"),
            (SpecialToken:[REDACTED], "</think>"),
            (SpecialToken::System, "<｜System｜>"),
            (SpecialToken::User, "<｜User｜>"),
            (SpecialToken::Assistant, "<｜Assistant｜>"),
            (SpecialToken:[REDACTED], "<｜latest_reminder｜>"),
            (SpecialToken::Dsml, "｜DSML｜"),
            (SpecialToken::Image, "<｜image｜>"),
            (SpecialToken::Ref, "<｜ref｜>"),
            (SpecialToken::RefEnd, "<｜/ref｜>"),
            (SpecialToken::Box, "<｜box｜>"),
            (SpecialToken::BoxEnd, "<｜/box｜>"),
            (SpecialToken::Point, "<｜point｜>"),
            (SpecialToken::PointEnd, "<｜/point｜>"),
            (SpecialToken::Polygon, "<｜polygon｜>"),
            (SpecialToken::PolygonEnd, "<｜/polygon｜>"),
        ];
        for (token, expected) in expected {
            assert_eq!(token.default_str(), expected);
            assert_eq!(DefaultSpecialTokens.token(token), expected);
        }
    }

    #[test]
    fn map_defaults_match_the_default_impl() {
        let map = SpecialTokensMap::default();
        let tokens = DefaultSpecialTokens;
        for token in ALL_TOKENS {
            assert_eq!(map.token(token), tokens.token(token));
        }
    }

    #[test]
    fn map_overrides_single_token() {
        let map = SpecialTokensMap {
            user: "<user>".to_string(),
            ..SpecialTokensMap::default()
        };
        assert_eq!(map.token(SpecialToken::User), "<user>");
        assert_eq!(
            map.token(SpecialToken::Assistant),
            SpecialToken:[REDACTED]
        );
    }
}

//! Python bindings for the special token mapping used in rendering and parsing.

use std::sync::Arc;

use deepseek_recipe_core::special_tokens::{SpecialToken, SpecialTokens, SpecialTokensMap};
use pyo3::prelude::*;

/// A kind of special token.
#[derive(Clone, Copy, PartialEq, Eq)]
#[pyclass(name = "SpecialToken", module = "deepseek_recipe._native", eq, frozen)]
pub(crate) enum PySpecialToken {
    Bos,
    Eos,
    ThinkingStart,
    ThinkingEnd,
    System,
    User,
    Assistant,
    LatestReminder,
    Dsml,
    Image,
    Ref,
    RefEnd,
    Box,
    BoxEnd,
    Point,
    PointEnd,
    Polygon,
    PolygonEnd,
}

impl PySpecialToken {
    fn to_core(self) -> SpecialToken {
        match self {
            Self::Bos => SpecialToken::Bos,
            Self::Eos => SpecialToken::Eos,
            Self::ThinkingStart => SpecialToken:[REDACTED],
            Self::ThinkingEnd => SpecialToken:[REDACTED],
            Self::System => SpecialToken::System,
            Self::User => SpecialToken::User,
            Self::Assistant => SpecialToken::Assistant,
            Self::LatestReminder => SpecialToken:[REDACTED],
            Self::Dsml => SpecialToken::Dsml,
            Self::Image => SpecialToken::Image,
            Self::Ref => SpecialToken::Ref,
            Self::RefEnd => SpecialToken::RefEnd,
            Self::Box => SpecialToken::Box,
            Self::BoxEnd => SpecialToken::BoxEnd,
            Self::Point => SpecialToken::Point,
            Self::PointEnd => SpecialToken::PointEnd,
            Self::Polygon => SpecialToken::Polygon,
            Self::PolygonEnd => SpecialToken::PolygonEnd,
        }
    }
}

#[pymethods]
impl PySpecialToken {
    /// Return the default literal spelling of this token.
    fn default_str(&self) -> String {
        self.to_core().default_str().to_string()
    }
}

/// A mapping from each `SpecialToken` to its spelling.
///
/// Every keyword defaults to the default spelling of its token, so only the
/// tokens being overridden need to be supplied.
#[pyclass(name = "SpecialTokens", module = "deepseek_recipe._native", frozen)]
pub(crate) struct PySpecialTokens {
    pub(crate) inner: Arc<dyn SpecialTokens>,
}

impl PySpecialTokens {
    pub(crate) fn from_core(inner: Arc<dyn SpecialTokens>) -> Self {
        Self { inner }
    }
}

#[pymethods]
impl PySpecialTokens {
    #[new]
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (*, bos = None, eos = None, thinking_start = None, thinking_end = None,
        system = None, user = None, assistant = None, latest_reminder = None, dsml = None,
        image = None, r#ref = None, ref_end = None, r#box = None, box_end = None, point = None,
        point_end = None, polygon = None, polygon_end = None))]
    fn new(
        bos: Option<String>,
        eos: Option<String>,
        thinking_start: Option<String>,
        thinking_end: Option<String>,
        system: Option<String>,
        user: Option<String>,
        assistant: Option<String>,
        latest_reminder: Option<String>,
        dsml: Option<String>,
        image: Option<String>,
        r#ref: Option<String>,
        ref_end: Option<String>,
        r#box: Option<String>,
        box_end: Option<String>,
        point: Option<String>,
        point_end: Option<String>,
        polygon: Option<String>,
        polygon_end: Option<String>,
    ) -> Self {
        let defaults = SpecialTokensMap::default();
        Self {
            inner: Arc::new(SpecialTokensMap {
                bos: bos.unwrap_or(defaults.bos),
                eos: eos.unwrap_or(defaults.eos),
                thinking_start: thinking_start.unwrap_or(defaults.thinking_start),
                thinking_end: thinking_end.unwrap_or(defaults.thinking_end),
                system: system.unwrap_or(defaults.system),
                user: user.unwrap_or(defaults.user),
                assistant: assistant.unwrap_or(defaults.assistant),
                latest_reminder: latest_reminder.unwrap_or(defaults.latest_reminder),
                dsml: dsml.unwrap_or(defaults.dsml),
                image: image.unwrap_or(defaults.image),
                r#ref: r#ref.unwrap_or(defaults.r#ref),
                ref_end: ref_end.unwrap_or(defaults.ref_end),
                r#box: r#box.unwrap_or(defaults.r#box),
                box_end: box_end.unwrap_or(defaults.box_end),
                point: point.unwrap_or(defaults.point),
                point_end: point_end.unwrap_or(defaults.point_end),
                polygon: polygon.unwrap_or(defaults.polygon),
                polygon_end: polygon_end.unwrap_or(defaults.polygon_end),
            }),
        }
    }

    /// Return the spelling of `token` in this mapping.
    fn token(&self, token: [REDACTED] -> String {
        self.inner.token(token.to_core()).to_string()
    }
}

//! Retrying an operation that might fail.

use std::future::Future;
use std::time::Duration;

/// Delays applied before repeated attempts of an operation.
///
/// A policy with `n` delays performs at most `n + 1` attempts.
#[derive(Debug, Clone, Default)]
pub struct RetryPolicy {
    delays: Vec<Duration>,
}

impl RetryPolicy {
    /// Return a policy that waits `delays` between attempts.
    pub fn new(delays: Vec<Duration>) -> Self {
        Self { delays }
    }

    /// Return a policy that performs one attempt.
    pub const fn none() -> Self {
        Self { delays: Vec::new() }
    }

    /// Return the policy used for image downloads: one retry after 0.3 seconds,
    /// one after 0.6 seconds, and one after 1.0 second.
    pub fn download() -> Self {
        Self {
            delays: vec![
                Duration::from_millis(300),
                Duration::from_millis(600),
                Duration::from_secs(1),
            ],
        }
    }

    /// Return the maximum number of attempts.
    pub fn max_attempts(&self) -> usize {
        self.delays.len() + 1
    }

    /// Run `operation` until it succeeds, fails without retrying, or runs out of
    /// attempts.
    ///
    /// `retryable` decides whether a failure starts another attempt. `attempt`
    /// passed to `operation` is the zero-based attempt index.
    ///
    /// # Errors
    ///
    /// Returns the error of the final attempt.
    pub async fn execute<T, E, F, Fut>(
        &self,
        mut operation: F,
        retryable: impl Fn(&E) -> bool,
    ) -> Result<T, E>
    where
        F: FnMut(usize) -> Fut,
        Fut: Future<Output = Result<T, E>>,
    {
        let mut attempt = 0;
        loop {
            let error = match operation(attempt).await {
                Ok(value) => return Ok(value),
                Err(error) => error,
            };
            let Some(delay) = self.delays.get(attempt) else {
                return Err(error);
            };
            if !retryable(&error) {
                return Err(error);
            }
            tokio::time::sleep(*delay).await;
            attempt += 1;
        }
    }
}

//! Image token counts for DeepSeek V4.1.

use std::fmt;

/// Result of fitting one image into the token budget.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ResizeResult {
    /// Number of token rows in the model token grid.
    pub n_llm_h: usize,
    /// Number of token columns in the model token grid.
    pub n_llm_w: usize,
    /// Resized image height in pixels.
    pub best_height: usize,
    /// Resized image width in pixels.
    pub best_width: usize,
    /// Image token count: the number of tokens the resized image occupies in
    /// the inference input.
    pub token_count: usize,
}

/// Failure to fit an image into the token budget.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CalcResizeError {
    /// Fitting the image did not reach a fixed point within the iteration limit.
    NotConverged {
        max_iter: usize,
        last_result: ResizeResult,
    },
}

impl fmt::Display for CalcResizeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NotConverged {
                max_iter,
                last_result,
            } => write!(
                f,
                "image resize did not converge after {max_iter} iterations, last result: {last_result:?}"
            ),
        }
    }
}

impl std::error::Error for CalcResizeError {}

/// DeepSeek V4.1 image token specification.
///
/// The specification maps an image size to its image token count. V4.1 uses
/// 14-pixel patches and a spatial downsample ratio of 3.
/// Images with a positive area below 544 * 544 pixels are upscaled before
/// patch alignment and token-budget fitting. This is an area target, not a
/// minimum for each dimension; token-budget fitting can reduce it further.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ImageTokenSpec {
    patch_size: usize,
    downsample_ratio: usize,
    max_token_count: usize,
    min_pixels: usize,
}

impl ImageTokenSpec {
    /// Return the DeepSeek V4.1 image token specification.
    ///
    /// Images are divided into 14-pixel patches, downsampled by 3 in each
    /// dimension, and limited to an image token count of 1024. Images with a
    /// positive area below 544 * 544 pixels are upscaled before alignment and
    /// budget fitting.
    pub const fn v41() -> Self {
        Self {
            patch_size: 14,
            downsample_ratio: 3,
            max_token_count: 1024,
            min_pixels: 544 * 544,
        }
    }

    /// Return the maximum image token count of one image.
    pub const fn max_token_count(&self) -> usize {
        self.max_token_count
    }

    /// Return the side length of one square patch in pixels.
    pub const fn patch_size(&self) -> usize {
        self.patch_size
    }

    /// Return the spatial downsampling ratio between the patch grid and the
    /// model token grid.
    pub const fn downsample_ratio(&self) -> usize {
        self.downsample_ratio
    }

    /// Return the image token count of an image of `width`×`height` pixels:
    /// the number of tokens it occupies in the inference input.
    ///
    /// # Errors
    ///
    /// Returns [`CalcResizeError`] when fitting the image does not converge.
    pub fn calc_token_count(&self, width: usize, height: usize) -> Result<usize, CalcResizeError> {
        self.calc_resize(width, height)
            .map(|result| result.token_count)
    }

    /// Return whether token-budget fitting leaves `width`×`height` unchanged.
    /// This checks dimensions only; it does not inspect encoded image bytes.
    /// Returns `false` when fitting does not converge.
    pub fn is_image_valid(&self, width: usize, height: usize) -> bool {
        self.calc_resize(width, height)
            .map(|result| result.best_width == width && result.best_height == height)
            .unwrap_or(false)
    }

    /// Return the target size and image token count for an image of
    /// `width`×`height` pixels.
    ///
    /// # Errors
    ///
    /// Returns [`CalcResizeError`] when fitting the image does not converge.
    pub fn calc_resize(
        &self,
        width: usize,
        height: usize,
    ) -> Result<ResizeResult, CalcResizeError> {
        const MAX_ITER: usize = 10;
        let mut result = self.calc_resize_once(width, height);
        for _ in 1..MAX_ITER {
            let next = self.calc_resize_once(result.best_width, result.best_height);
            if next == result {
                return Ok(result);
            }
            result = next;
        }
        Err(CalcResizeError::NotConverged {
            max_iter: MAX_ITER,
            last_result: result,
        })
    }

    /// Upscale to the minimum area, align to patches, and fit the token budget.
    fn calc_resize_once(&self, width: usize, height: usize) -> ResizeResult {
        let mut width = width;
        let mut height = height;

        let current_pixels = width * height;
        if current_pixels < self.min_pixels && current_pixels > 0 {
            let ratio = (self.min_pixels as f64 / current_pixels as f64).sqrt();
            width = (width as f64 * ratio) as usize;
            height = (height as f64 * ratio) as usize;
        }

        let best_width = width.div_ceil(self.patch_size) * self.patch_size;
        let best_height = height.div_ceil(self.patch_size) * self.patch_size;
        self.fit_token_budget(height, width, best_height, best_width)
    }

    /// Return the aligned size `best_width`×`best_height` if it fits the token
    /// budget; otherwise solve once for the largest aspect-preserving size
    /// within the budget.
    fn fit_token_budget(
        &self,
        height: usize,
        width: usize,
        best_height: usize,
        best_width: usize,
    ) -> ResizeResult {
        let mut result = self.resize_result(best_height, best_width);
        if result.token_count > self.max_token_count {
            result = self.solve_resize_ratio(height, width, self.max_token_count);
            assert!(
                result.token_count <= self.max_token_count,
                "token budget must be satisfied after one solve"
            );
        }
        result
    }

    /// Return the token grid and image token count of a
    /// `best_width`×`best_height` image that is already aligned to patches.
    fn resize_result(&self, best_height: usize, best_width: usize) -> ResizeResult {
        let n_llm_h = (best_height / self.patch_size).div_ceil(self.downsample_ratio);
        let n_llm_w = (best_width / self.patch_size).div_ceil(self.downsample_ratio);
        ResizeResult {
            n_llm_h,
            n_llm_w,
            best_height,
            best_width,
            token_count: self.calc_grid_token_count(n_llm_h, n_llm_w),
        }
    }

    /// Return the image token count of a token grid with `n_llm_h` rows and
    /// `n_llm_w` columns.
    ///
    /// Each row holds one token per column and one newline token, and a start
    /// token and an end token delimit the image.
    fn calc_grid_token_count(&self, n_llm_h: usize, n_llm_w: usize) -> usize {
        n_llm_h * (n_llm_w + 1) + 2
    }

    /// Solve for the largest aspect-preserving size within `max_token_count`.
    fn solve_resize_ratio(
        &self,
        height: usize,
        width: usize,
        max_token_count: usize,
    ) -> ResizeResult {
        let ratio = height as f64 / width as f64;
        let max_w_float = ((max_token_count as f64 - 2.0) / ratio + 0.25).sqrt() - 0.5;
        let max_h_float = max_w_float * ratio;

        let (best_height, best_width);
        if max_w_float < 1.0 {
            let max_w = 1;
            let max_h = (max_token_count - 2) / (max_w + 1);
            best_width = max_w * self.patch_size * self.downsample_ratio;
            best_height = max_h * self.patch_size * self.downsample_ratio;
        } else if max_h_float < 1.0 {
            let max_h = 1;
            let max_w = (max_token_count - 2) / max_h - 1;
            assert!(max_w > 1, "token budget must allow a two-column grid");
            best_width = max_w * self.patch_size * self.downsample_ratio;
            best_height = max_h * self.patch_size * self.downsample_ratio;
        } else {
            let max_w = max_w_float as usize;
            let max_h = max_h_float as usize;
            let beta_w = (max_w * self.patch_size * self.downsample_ratio) as f64 / width as f64;
            let beta_h = (max_h * self.patch_size * self.downsample_ratio) as f64 / height as f64;
            let beta = beta_w.min(beta_h);
            best_width = (width as f64 * beta / self.patch_size as f64) as usize * self.patch_size;
            best_height =
                (height as f64 * beta / self.patch_size as f64) as usize * self.patch_size;
        }
        self.resize_result(best_height, best_width)
    }
}

