    /// a system message requires the V4.1 prompt encoding.
    pub defer_loading: bool,
}

/// Normalized tool selection for a rendered conversation.
///
/// Rendering includes the tool prompt only when the conversation defines at
/// least one tool. Without the tool prompt, rendering also omits the reasoning
/// content of historical assistant messages.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum ToolChoice {
    /// Rendering includes the tool prompt, and the model can answer or call a
    /// tool.
    #[default]
    Auto,
    /// Rendering omits the tool prompt and, as a consequence, the reasoning
    /// content of historical assistant messages.
    None,
    /// Rendering includes the tool prompt and, when at least one tool is
    /// defined, starts the assistant output inside a tool-call block.
    Required,
}

//! The exception raised when a protocol request cannot be converted.

use deepseek_recipe::request::ConversionError as RustConversionError;
use pyo3::exceptions::PyException;
use pyo3::prelude::*;

pyo3::create_exception!(
    _native,
    ConversionError,
    PyException,
    "Raised when a protocol request is invalid or cannot be converted."
);

/// Build the exception for a failed conversion.
///
/// The exception message is the conversion error message. Its `status_code` and
/// `body` attributes hold the HTTP status and serialized JSON error response.
pub(crate) fn request_error(py: Python<'_>, error: RustConversionError) -> PyErr {
    let status_code = error.status_code();
    let response = error.into_error_response();
    let body = match serde_json::to_string(&response) {
        Ok(body) => body,
        Err(error) => return pyo3::exceptions::PyRuntimeError::new_err(error.to_string()),
    };
    let exception = ConversionError::new_err(response.error.message);
    let value = exception.value(py);
    if let Err(error) = value
        .setattr("status_code", status_code)
        .and_then(|()| value.setattr("body", body))
    {
        return error;
    }
    exception
}

